function makeRectStroke(
  id: string,
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  color: string,
  width = 2.0,
  layerId = 'layer-1'
): StrokeObject {
  return {
    id,
    layerId,
    tool: 'pen',
    penType: 'ballpoint',
    isShape: true,
    shapeType: 'rectangle',
    color,
    width,
    opacity: 1,
    points: [
      { x: x1, y: y1, pressure: 0.8 },
      { x: x2, y: y1, pressure: 0.8 },
      { x: x2, y: y2, pressure: 0.8 },
      { x: x1, y: y2, pressure: 0.8 },
      { x: x1, y: y1, pressure: 0.8 },
    ],
  };
}

function makeCircleStroke(
  id: string,
  cx: number,
  cy: number,
  r: number,
  color: string,
  width = 2.0,
  layerId = 'layer-1'
): StrokeObject {
  const pts = [];
  const steps = 40;
  for (let i = 0; i <= steps; i++) {
    const a = (i / steps) * Math.PI * 2;
    pts.push({
      x: Math.round((cx + Math.cos(a) * r) * 10) / 10,
      y: Math.round((cy + Math.sin(a) * r) * 10) / 10,
      pressure: 0.8,
    });
  }
  return {
    id,
    layerId,
    tool: 'pen',
    penType: 'ballpoint',
    isShape: true,
    shapeType: 'circle',
    color,
    width,
    opacity: 1,
    points: pts,
  };
}

function makeLineStroke(
  id: string,
  pts: Array<[number, number]>,
  color: string,
  width = 2.0,
  isArrow = false,
  layerId = 'layer-1'
): StrokeObject {
  const strokePts = pts.map(([x, y]) => ({ x, y, pressure: 0.8 }));
  if (isArrow && pts.length >= 2) {
    const [x1, y1] = pts[pts.length - 2];
    const [x2, y2] = pts[pts.length - 1];
    const angle = Math.atan2(y2 - y1, x2 - x1);
    const headLen = 10;
    const a1 = angle - Math.PI * 0.82;
    const a2 = angle + Math.PI * 0.82;
    strokePts.push(
      { x: Math.round(x2 + Math.cos(a1) * headLen), y: Math.round(y2 + Math.sin(a1) * headLen), pressure: 0.8 },
      { x: x2, y: y2, pressure: 0.8 },
      { x: Math.round(x2 + Math.cos(a2) * headLen), y: Math.round(y2 + Math.sin(a2) * headLen), pressure: 0.8 }
    );
  }
  return {
    id,
    layerId,
    tool: 'pen',
    penType: 'ballpoint',
    isShape: true,
    shapeType: isArrow ? 'arrow' : 'line',
    color,
    width,
    opacity: 1,
    points: strokePts,
  };
}

